use lean_runtime::semantics::hash;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &Vec<u8>, n: u64) -> u64 {
    let b = &inp[..];
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, hash::byte_array_hash(black_box(b)));
    }
    acc
}

fn main() {
    run(|| mixed().into_bytes(), kernel)
}
